using System.Text.Json;
using McpServer.Support.Mcp.Tests.Infrastructure;

namespace McpServer.Support.Mcp.Tests.Documentation;

/// <summary>
/// TEST-MCP-USECASE-020-AC006: Replays the exact-final annotated Git evidence object instead of
/// accepting source-shape assertions or an unbound working-tree projection.
/// </summary>
public sealed class BugTriage139TwentyFourthEvidenceTests
{
    private const string RequiredBase = "210cb223d81dac6b4045b868e4d7b2712d08b752";
    private const string ContractRelativePath =
        "docs/receipts/BUG-TRIAGE-139-twenty-fourth-exact-final-contract.json";

    /// <summary>
    /// Verifies that the committed contract names an annotated local Git object whose structured
    /// manifest binds the required base, the actual candidate SHA/tree, clean status, commands,
    /// result hashes, and zero-skip test counts.
    /// </summary>
    [Fact]
    public void ExactFinalEvidenceTag_BindsRequiredBaseCandidateTreeAndCommandReceipts()
    {
        var root = RepositoryEvidenceTestSupport.ResolveRepositoryRoot();
        var contractPath = Path.Combine(root, ContractRelativePath.Replace('/', Path.DirectorySeparatorChar));
        Assert.True(File.Exists(contractPath), $"Missing exact-final evidence contract: {contractPath}");

        using var contract = JsonDocument.Parse(File.ReadAllText(contractPath));
        var contractRoot = contract.RootElement;
        Assert.Equal(1, contractRoot.GetProperty("schemaVersion").GetInt32());
        Assert.Equal(RequiredBase, contractRoot.GetProperty("requiredBaseSha").GetString());
        var tagName = contractRoot.GetProperty("annotatedTag").GetString();
        Assert.False(string.IsNullOrWhiteSpace(tagName));

        var tagReference = "refs/tags/" + tagName;
        var candidateSha = RepositoryEvidenceTestSupport.RunGitText(
                root,
                ["rev-parse", tagReference + "^{commit}"])
            .Trim();
        var currentSha = RepositoryEvidenceTestSupport.RunGitText(root, ["rev-parse", "HEAD"]).Trim();
        Assert.Equal(currentSha, candidateSha);
        var candidateTree = RepositoryEvidenceTestSupport.RunGitText(
                root,
                ["rev-parse", candidateSha + "^{tree}"])
            .Trim();
        Assert.Equal(
            0,
            RepositoryEvidenceTestSupport.RunGit(root, ["merge-base", "--is-ancestor", RequiredBase, candidateSha])
                .ExitCode);
        Assert.Equal(
            string.Empty,
            RepositoryEvidenceTestSupport.RunGitText(root, ["status", "--porcelain=v1"]).Trim());

        var annotation = RepositoryEvidenceTestSupport.RunGitText(
            root,
            ["for-each-ref", "--format=%(contents)", tagReference]);
        using var evidence = JsonDocument.Parse(annotation);
        var evidenceRoot = evidence.RootElement;
        Assert.Equal(1, evidenceRoot.GetProperty("schemaVersion").GetInt32());
        Assert.Equal(RequiredBase, evidenceRoot.GetProperty("requiredBaseSha").GetString());
        Assert.Equal(candidateSha, evidenceRoot.GetProperty("candidateSha").GetString());
        Assert.Equal(candidateTree, evidenceRoot.GetProperty("candidateTree").GetString());
        Assert.Equal("clean", evidenceRoot.GetProperty("worktreeStatus").GetString());

        var commandReceipts = evidenceRoot.GetProperty("commandReceipts");
        Assert.True(commandReceipts.GetArrayLength() > 0);
        foreach (var receipt in commandReceipts.EnumerateArray())
        {
            Assert.False(string.IsNullOrWhiteSpace(receipt.GetProperty("command").GetString()));
            Assert.Equal(0, receipt.GetProperty("exitCode").GetInt32());
            Assert.Matches("^[0-9A-F]{64}$", receipt.GetProperty("outputSha256").GetString());
            Assert.True(receipt.GetProperty("total").GetInt32() >= 0);
            Assert.Equal(0, receipt.GetProperty("failed").GetInt32());
            Assert.Equal(0, receipt.GetProperty("skipped").GetInt32());
        }
    }
}

